// E-mail del lead al cliente: stesso impianto del report mensile (tabelle e stili inline, apici singoli).
const b = $('Webhook').item.json.body || {};
const c = $json; // riga del registro Clienti
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pulisci = s => String(s ?? '').trim();
const nome = pulisci(b.nome), telefono = pulisci(b.telefono), email = pulisci(b.email), citta = pulisci(b.citta), messaggio = pulisci(b.messaggio);
const telHref = 'tel:' + telefono.replace(/[^+\d]/g, '');
const quando = $now.setZone('Europe/Rome');
const data = quando.setLocale('it').toFormat('d MMMM yyyy') + ' alle ' + quando.toFormat('HH:mm');
const saluto = pulisci(c.referente).replace(/\([^)]*\)/g, '').trim() || pulisci(c.azienda);
const F = 'font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;';
const INK = '#1c1c1a', MUTED = '#6b6b66', LINE = '#e5e5e0';
const riga = (k, v, href) => '<tr><td width=\'120\' valign=\'top\' style=\'' + F + 'font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:' + MUTED + ';padding:12px 12px 12px 0;border-bottom:1px solid ' + LINE + ';\'>' + k + '</td><td valign=\'top\' style=\'' + F + 'font-size:16px;color:' + INK + ';padding:12px 0;border-bottom:1px solid ' + LINE + ';\'>' + (href ? '<a href=\'' + esc(href) + '\' style=\'color:' + INK + ';text-decoration:underline;\'>' + esc(v) + '</a>' : esc(v)) + '</td></tr>';
const righe = riga('Nome', nome) + riga('Telefono', telefono, telHref) + (email ? riga('E-mail', email, 'mailto:' + email) : '') + (citta ? riga('Citt\u00e0', citta) : '');
const subject = 'Nuova richiesta di preventivo da ' + nome + (citta ? ' (' + citta + ')' : '');
const html = '<!DOCTYPE html><html lang=\'it\'><head><meta charset=\'utf-8\'><meta name=\'viewport\' content=\'width=device-width\'><title>' + esc(subject) + '</title></head>'
  + '<body style=\'margin:0;padding:0;background:#efefec;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\' style=\'background:#efefec;\'><tr><td align=\'center\' style=\'padding:32px 12px;\'>'
  + '<table width=\'600\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\' style=\'max-width:600px;width:100%;background:#ffffff;\'>'
  + '<tr><td style=\'padding:22px 36px;background:' + INK + ';\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'><tr><td style=\'' + F + 'font-size:13px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:#ffffff;\'>ConsulBuild</td><td align=\'right\' style=\'' + F + 'font-size:12px;color:#c9c9c4;\'>Nuova richiesta dal tuo sito</td></tr></table></td></tr>'
  + '<tr><td style=\'padding:32px 36px 40px;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>'
  + '<tr><td><div style=\'' + F + 'font-size:26px;line-height:1.2;font-weight:700;color:' + INK + ';\'>' + esc(nome) + '</div><div style=\'' + F + 'font-size:14px;color:' + MUTED + ';margin-top:6px;\'>' + esc(c.dominio || '') + ' \u00b7 ' + esc(data) + '</div></td></tr>'
  + '<tr><td style=\'padding-top:22px;\'><div style=\'' + F + 'font-size:15px;line-height:1.55;color:' + INK + ';\'>Buongiorno ' + esc(saluto) + ',<br>una persona ha compilato il modulo di preventivo sul tuo sito. Ecco i suoi recapiti: pi\u00f9 in fretta rispondi, pi\u00f9 \u00e8 probabile che il lavoro sia tuo.</div></td></tr>'
  + '<tr><td style=\'padding-top:24px;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>' + righe + '</table></td></tr>'
  + (messaggio ? '<tr><td style=\'padding-top:28px;\'><div style=\'' + F + 'font-size:12px;letter-spacing:.08em;text-transform:uppercase;font-weight:600;color:' + MUTED + ';padding-bottom:10px;\'>Il suo messaggio</div><div style=\'' + F + 'font-size:16px;line-height:1.55;color:' + INK + ';padding:18px 20px;background:#f7f7f5;border-left:3px solid ' + INK + ';white-space:pre-wrap;\'>' + esc(messaggio) + '</div></td></tr>' : '')
  + '<tr><td style=\'padding-top:28px;\'><table cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'><tr><td style=\'background:' + INK + ';\'><a href=\'' + esc(telHref) + '\' style=\'' + F + 'display:inline-block;padding:14px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;\'>Chiama ' + esc(nome.split(' ')[0]) + '</a></td><td style=\'width:12px;\'></td>' + (email ? '<td style=\'border:1px solid ' + INK + ';\'><a href=\'mailto:' + esc(email) + '\' style=\'' + F + 'display:inline-block;padding:13px 22px;font-size:15px;font-weight:600;color:' + INK + ';text-decoration:none;\'>Scrivi un\u2019e-mail</a></td>' : '') + '</tr></table>' + (email ? '<div style=\'' + F + 'font-size:13px;color:' + MUTED + ';margin-top:12px;\'>Puoi anche rispondere direttamente a questa e-mail: arriva a ' + esc(nome) + '.</div>' : '') + '</td></tr>'
  + '</table></td></tr>'
  + '<tr><td style=\'padding:20px 36px 24px;border-top:1px solid ' + LINE + ';\'><div style=\'' + F + 'font-size:12px;line-height:1.6;color:' + MUTED + ';\'>Richiesta ricevuta dal modulo di ' + esc(c.dominio || '') + ' e recapitata da <strong style=\'color:' + INK + ';\'>ConsulBuild</strong> \u00b7 info@consulbuild.com<br>I dati del richiedente sono stati inviati solo a te.</div></td></tr>'
  + '</table></td></tr></table></body></html>';
const text = 'CONSULBUILD \u2014 Nuova richiesta dal tuo sito\n' + (c.dominio || '') + ' \u00b7 ' + data + '\n\nBuongiorno ' + saluto + ',\nuna persona ha compilato il modulo di preventivo sul tuo sito.\n\nNome: ' + nome + '\nTelefono: ' + telefono + (email ? '\nE-mail: ' + email : '') + (citta ? '\nCitt\u00e0: ' + citta : '') + (messaggio ? '\n\nIl suo messaggio:\n' + messaggio : '') + '\n\n' + (email ? 'Rispondi a questa e-mail per scrivere direttamente a ' + nome + '.\n\n' : '') + 'Richiesta recapitata da ConsulBuild \u00b7 info@consulbuild.com\n';
return [{ json: { ...c, subject, html, text, replyTo: email || 'info@consulbuild.com' } }];
